import json

with open('log-277.jsonl') as f:
    lines = f.readlines()

for i, line in enumerate(lines, 1):
    try:
        obj = json.loads(line)
    except Exception as e:
        print(i, "PARSE ERROR", e)
        continue
    ts = obj.get('timestamp', '')
    typ = obj.get('type', '')
    role = None
    summary = ''
    msg = obj.get('message')
    if msg:
        role = msg.get('role')
        content = msg.get('content')
        if isinstance(content, str):
            summary = content[:200].replace('\n', ' ')
        elif isinstance(content, list):
            parts = []
            for c in content:
                ctype = c.get('type')
                if ctype == 'text':
                    parts.append('TEXT:' + c.get('text','')[:150].replace('\n',' '))
                elif ctype == 'tool_use':
                    parts.append(f"TOOL_USE:{c.get('name')} input={json.dumps(c.get('input',{}))[:200]}")
                elif ctype == 'tool_result':
                    cont = c.get('content')
                    if isinstance(cont, list):
                        s = ' '.join([x.get('text','')[:150] for x in cont if isinstance(x,dict)])
                    else:
                        s = str(cont)[:150]
                    err = c.get('is_error')
                    parts.append(f"TOOL_RESULT err={err} :{s}".replace('\n',' '))
            summary = ' | '.join(parts)
    elif obj.get('type') == 'attachment':
        summary = f"ATTACHMENT hook={obj.get('attachment',{}).get('hookName')}"
    print(f"{i}\t{ts}\t{typ}\t{role}\t{summary[:300]}")
EOF

