import json
with open('/tmp/claude-0/-home-user-Shepherd/bde11c71-e724-5bfb-ac6f-cb6291c77c5d/scratchpad/log-269.jsonl') as f:
    lines = f.readlines()

def get_text(content):
    out = []
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        for c in content:
            if not isinstance(c, dict): continue
            t = c.get('type')
            if t == 'text':
                out.append('[TEXT] ' + c.get('text','')[:2000])
            elif t == 'tool_use':
                out.append('[TOOL_USE] ' + c.get('name','') + ' ' + json.dumps(c.get('input',{}))[:1500])
            elif t == 'tool_result':
                cont = c.get('content')
                if isinstance(cont, list):
                    s = ''
                    for cc in cont:
                        if isinstance(cc, dict) and cc.get('type')=='text':
                            s += cc.get('text','')
                    out.append('[TOOL_RESULT] ' + s[:1500])
                else:
                    out.append('[TOOL_RESULT] ' + str(cont)[:1500])
    return '\n'.join(out)

for i, l in enumerate(lines):
    obj = json.loads(l)
    t = obj.get('type')
    if t in ('user','assistant'):
        msg = obj.get('message', {})
        role = msg.get('role')
        content = msg.get('content')
        text = get_text(content)
        ts = obj.get('timestamp')
        print(f'--- [{i}] {ts} {role} ---')
        print(text[:2500])
        print()
