import json, sys

path = sys.argv[1]
with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception as e:
            print("PARSE_ERR", e)
            continue
        ts = d.get("timestamp", "")
        typ = d.get("type", "")
        msg = d.get("message", {})
        role = msg.get("role", "")
        content = msg.get("content", "")
        out = []
        if isinstance(content, str):
            out.append(content[:300])
        elif isinstance(content, list):
            for c in content:
                if not isinstance(c, dict):
                    continue
                ct = c.get("type")
                if ct == "text":
                    out.append("TEXT: " + c.get("text", "")[:300])
                elif ct == "tool_use":
                    inp = json.dumps(c.get("input", {}))[:250]
                    out.append(f"TOOL_USE[{c.get('name')}]: {inp}")
                elif ct == "tool_result":
                    cc = c.get("content", "")
                    if isinstance(cc, list):
                        cc = " ".join(x.get("text","")[:200] for x in cc if isinstance(x,dict))
                    out.append("TOOL_RESULT: " + str(cc)[:250])
        joined = " | ".join(out)
        print(f"{ts} [{typ}/{role}] {joined}")

